from pyspark.sql import functions as F


def solve(sensor_readings):
    return sensor_readings.select(
        "reading_id",
        "device_id",
        F.to_date("arrival_time").alias("reading_date"),
        (F.col("arrival_time") - F.col("event_time")).alias("late_s"),
        F.col("payload.status").alias("status"),
        F.col("firmware.build").alias("firmware_build"),
    )
